const expected = ($vars.ACI_WEBHOOK_TOKEN || '').trim();
const headers = $input.first().json.headers || {};
const received = (headers['x-aci-token'] || headers['X-ACI-Token'] || '').trim();

if (!expected) {
  return $input.all();
}

if (received !== expected) {
  throw new Error('Unauthorized: missing or invalid X-ACI-Token header');
}

return $input.all();

return $input.all().map(i => ({
  json: {
    ...i.json,
    headline: i.json.title || `${i.json.event_type} — ${i.json.location || i.json.country}`,
    intelligence_summary: i.json.description || `A ${i.json.event_type} event was reported (confidence too low for full analysis).`,
    severity: i.json.confidence >= 0.40 ? 'Monitor' : 'Low',
    recommended_actions: ['Continue monitoring'],
    information_gaps: i.json.source_count < 2 ? ['Independent corroborating source'] : [],
    ai: null
  }
}));

const now = new Date();
const from = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const fmt = d => d.toISOString().slice(0,10);

const scope = ($vars.ACI_SCOPE || 'EAST_AFRICA').trim().toUpperCase();

const EAST_AFRICA = [
  'Ethiopia','Kenya','Uganda','Tanzania','Rwanda','Burundi',
  'South Sudan','Somalia','Djibouti','Eritrea'
];

let countries, bbox, news_scope, acled_region;

if (scope === 'AFRICA') {
  countries = [];
  bbox = {minLat:-35.5,maxLat:37.5,minLon:-18.0,maxLon:55.0};
  news_scope = 'Africa';
  acled_region = null;
} else if (scope === 'ETHIOPIA') {
  countries = ['Ethiopia'];
  bbox = {minLat:3.0,maxLat:15.2,minLon:32.8,maxLon:48.3};
  news_scope = 'Ethiopia';
  acled_region = null;
} else {
  countries = EAST_AFRICA;
  bbox = {minLat:-12.5,maxLat:18.5,minLon:28.0,maxLon:52.5};
  news_scope = '"East Africa" OR Ethiopia OR Kenya OR Uganda OR Tanzania OR Rwanda OR Burundi OR "South Sudan" OR Somalia OR Djibouti OR Eritrea';
  acled_region = 3;
}

return [{json:{
  scope,
  target_country: scope === 'ETHIOPIA' ? 'Ethiopia' : '',
  countries,
  bbox,
  news_scope,
  acled_region,
  from_date:fmt(from),
  to_date:fmt(now),
  generated_at:now.toISOString()
}}];

const payload = $json;
const rows = Array.isArray(payload.data) ? payload.data : [];
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;

return rows
  .filter(r => {
    const d = new Date(r.event_date || r.timestamp || 0);
    return !Number.isNaN(d.getTime()) && d.getTime() >= cutoff;
  })
  .map(r => ({
    json: {
      source: 'ACLED',
      source_type: 'structured_conflict',
      source_event_id: r.event_id_cnty || r.event_id_no_cnty || '',
      event_type: r.event_type || 'Conflict',
      sub_event_type: r.sub_event_type || '',
      title: `${r.event_type || 'Conflict'} — ${r.location || r.admin1 || r.country || ''}`,
      description: r.notes || '',
      country: r.country || '',
      admin1: r.admin1 || '',
      location: r.location || r.admin1 || '',
      latitude: Number(r.latitude) || null,
      longitude: Number(r.longitude) || null,
      event_time: r.event_date || '',
      actors: [r.actor1, r.actor2].filter(Boolean),
      fatalities: Number(r.fatalities) || 0,
      source_url: 'https://acleddata.com/',
      credibility_base: 0.30,
      raw: r
    }
  }));

const p=$json;
const features=Array.isArray(p.features)?p.features:[];
const cfg=$('Config + Date Window1').first().json;
const allowed=(cfg.countries||[]).map(x=>x.toLowerCase());

const eventTypeMap={EQ:'Earthquake',TC:'Cyclone',FL:'Flood',VO:'Volcano',WF:'Wildfire',DR:'Drought'};

function countryText(pr){
  const a=pr.country||pr.countryname||'';
  const b=Array.isArray(pr.affectedcountries)?pr.affectedcountries.map(x=>typeof x==='string'?x:(x.countryname||x.name||'')).join(', '):'';
  return (a||b||'').trim();
}
function allowedCountry(text){
  if(cfg.scope==='AFRICA') return true;
  if(!allowed.length) return true;
  const s=String(text||'').toLowerCase();
  return allowed.some(c=>s.includes(c));
}

return features.map(f=>{
  const pr=f.properties||{}, coords=f.geometry?.coordinates||[];
  const code=pr.eventtype||pr.eventType||pr.type||'';
  const country=countryText(pr);
  return {
    source:'GDACS',source_type:'official_disaster',
    source_event_id:String(pr.eventid||pr.eventId||pr.id||''),
    event_type:eventTypeMap[code]||code||'Disaster',
    sub_event_type:pr.alertlevel||pr.alertLevel||'',
    title:pr.name||pr.eventname||`${eventTypeMap[code]||'Disaster'} — ${country}`,
    description:pr.description||pr.severitydata?.htmldescription||pr.severitydata?.description||'',
    country,admin1:'',location:pr.name||country||'',
    latitude:Array.isArray(coords)&&coords.length>=2?Number(coords[1]):null,
    longitude:Array.isArray(coords)&&coords.length>=2?Number(coords[0]):null,
    event_time:pr.fromdate||pr.fromDate||pr.datemodified||pr.date||'',
    actors:[],fatalities:Number(pr.severitydata?.deaths||0)||0,
    source_url:pr.url||pr.link||'https://gdacs.org/',
    credibility_base:0.30,raw:pr
  };
}).filter(x=>allowedCountry(x.country)).map(json=>({json}));

function detectType(t=''){
  const s=t.toLowerCase();
  if(s.includes('drone strike')||s.includes('airstrike')||s.includes('air strike')) return 'Conflict';
  if(s.includes('flood')) return 'Flood';
  if(s.includes('drought')) return 'Drought';
  if(s.includes('earthquake')) return 'Earthquake';
  if(s.includes('wildfire')||s.includes('forest fire')) return 'Wildfire';
  if(s.includes('cyclone')||s.includes('storm')) return 'Cyclone';
  if(s.includes('conflict')||s.includes('clash')||s.includes('attack')||s.includes('violence')||s.includes('fighting')||s.includes('war')) return 'Conflict';
  if(s.includes('displacement')||s.includes('displaced')) return 'Displacement';
  if(s.includes('epidemic')||s.includes('outbreak')) return 'Health Emergency';
  if(s.includes('food insecurity')||s.includes('famine')) return 'Food Security';
  return 'Emerging Crisis';
}

const places=[
 ['Mekelle','Tigray','Ethiopia'],['Addis Ababa','Addis Ababa','Ethiopia'],['Dire Dawa','Dire Dawa','Ethiopia'],
 ['Bahir Dar','Amhara','Ethiopia'],['Gondar','Amhara','Ethiopia'],['Adama','Oromia','Ethiopia'],
 ['Jigjiga','Somali','Ethiopia'],['Hawassa','Sidama','Ethiopia'],['Semera','Afar','Ethiopia'],
 ['Tigray','Tigray','Ethiopia'],['Amhara','Amhara','Ethiopia'],['Oromia','Oromia','Ethiopia'],['Afar','Afar','Ethiopia'],
 ['Nairobi','Nairobi','Kenya'],['Mombasa','Mombasa','Kenya'],['Kisumu','Kisumu','Kenya'],['Kenya','','Kenya'],
 ['Kampala','Kampala','Uganda'],['Uganda','','Uganda'],
 ['Kigali','Kigali','Rwanda'],['Rwanda','','Rwanda'],
 ['Bujumbura','Bujumbura','Burundi'],['Burundi','','Burundi'],
 ['Juba','Juba','South Sudan'],['South Sudan','','South Sudan'],
 ['Mogadishu','Mogadishu','Somalia'],['Hargeisa','Hargeisa','Somalia'],['Somalia','','Somalia'],
 ['Djibouti','Djibouti','Djibouti'],
 ['Asmara','Asmara','Eritrea'],['Eritrea','','Eritrea'],
 ['Dar es Salaam','Dar es Salaam','Tanzania'],['Arusha','Arusha','Tanzania'],['Tanzania','','Tanzania'],
 ['Ethiopia','','Ethiopia']
];

function locate(text){
  const s=text.toLowerCase();
  for(const [needle,admin1,country] of places){
    if(s.includes(needle.toLowerCase())) return {location:needle,admin1,country};
  }
  return {location:'',admin1:'',country:''};
}

return $input.all().map(i=>{
  const r=i.json,title=r.title||'',body=r.contentSnippet||r.content||r.description||'';
  const combined=`${title} ${body}`,g=locate(combined);
  return {json:{
    source:'NEWS',source_type:'open_news',source_event_id:r.guid||r.id||r.link||'',
    event_type:detectType(combined),sub_event_type:'',title,description:body,
    country:g.country,admin1:g.admin1,location:g.location,
    latitude:null,longitude:null,event_time:r.isoDate||r.pubDate||'',
    actors:[],fatalities:0,source_url:r.link||'',credibility_base:0.40,raw:r
  }};
});

const b = $json.body || $json;
const now = new Date().toISOString();

const clean = (str, max = 500) => String(str || '').replace(/<[^>]*>/g, '').trim().slice(0, max);

const lat = b.latitude != null ? Number(b.latitude) : null;
const lon = b.longitude != null ? Number(b.longitude) : null;
const fatalities = Math.max(0, Number(b.fatalities || 0) || 0);

if (lat !== null && (!Number.isFinite(lat) || lat < -90 || lat > 90)) {
  throw new Error('Invalid latitude');
}
if (lon !== null && (!Number.isFinite(lon) || lon < -180 || lon > 180)) {
  throw new Error('Invalid longitude');
}

return [{
  json: {
    source: 'COMMUNITY',
    source_type: 'community_report',
    source_event_id: b.report_id || `community-${Date.now()}`,
    event_type: clean(b.event_type, 80) || 'Emerging Crisis',
    sub_event_type: clean(b.sub_event_type, 80),
    title: clean(b.title, 200) || `${clean(b.event_type) || 'Crisis'} community report — ${clean(b.location || b.country)}`,
    description: clean(b.description, 1000),
    country: clean(b.country, 80) || 'Ethiopia',
    admin1: clean(b.admin1, 80),
    location: clean(b.location || b.admin1 || b.country, 120),
    latitude: lat,
    longitude: lon,
    event_time: b.event_time || now,
    actors: Array.isArray(b.actors) ? b.actors.map(a => clean(a, 60)).filter(Boolean) : [],
    fatalities,
    source_url: clean(b.source_url, 300),
    credibility_base: 0.05,
    raw: b
  }
}];

const current = $input.all()
  .map(i => i.json)
  .filter(x => x && x.source && x.event_type);

function norm(s = '') {
  return String(s).toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function dateKey(s) {
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? 'unknown' : d.toISOString().slice(0, 10);
}
function hoursOld(s) {
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? 9999 : Math.max(0, (Date.now() - d.getTime()) / 36e5);
}
function meaningfulLoc(e) {
  const loc = norm(e.location || e.admin1 || '');
  const country = norm(e.country || '');
  return loc && loc !== country ? loc : country || 'unknown';
}
function tokens(s) {
  return norm(s).split(' ').filter(x => x.length >= 4);
}
function textOf(e) {
  return norm(`${e.title || ''} ${e.description || ''} ${e.location || ''} ${e.admin1 || ''}`);
}

const broad = new Map();

for (const e of current) {
  const broadKey = [
    norm(e.country || 'unknown'),
    norm(e.event_type || 'crisis'),
    dateKey(e.event_time)
  ].join('|');

  if (!broad.has(broadKey)) broad.set(broadKey, []);
  broad.get(broadKey).push(e);
}

const output = [];

for (const [broadKey, events] of broad.entries()) {
  if (!events.length) continue;

  const structured = events.filter(e => e.source !== 'NEWS');
  const news = events.filter(e => e.source === 'NEWS');

  const groups = [];

  if (structured.length) {
    const locMap = new Map();

    for (const e of structured) {
      const loc = meaningfulLoc(e);
      if (!locMap.has(loc)) locMap.set(loc, []);
      locMap.get(loc).push(e);
    }

    for (const [loc, base] of locMap.entries()) {
      const locTokens = tokens(loc);
      const matchedNews = news.filter(n => {
        const t = textOf(n);
        return locTokens.length === 0 ? false : locTokens.some(tok => t.includes(tok));
      });
      groups.push([...base, ...matchedNews]);
    }

    const attached = new Set(groups.flat().filter(e => e.source === 'NEWS').map(e => e.source_event_id));
    for (const n of news) {
      if (!attached.has(n.source_event_id)) groups.push([n]);
    }
  } else {
    const newsMap = new Map();
    for (const n of news) {
      const loc = meaningfulLoc(n);
      if (!newsMap.has(loc)) newsMap.set(loc, []);
      newsMap.get(loc).push(n);
    }
    groups.push(...newsMap.values());
  }

  for (const group of groups) {
    if (!group.length) continue;

    const primary = [...group].sort((a, b) => (b.credibility_base || 0) - (a.credibility_base || 0))[0];
    const sources = [...new Set(group.map(e => e.source))];

    const credibility = Math.min(0.40, Math.max(...group.map(e => Number(e.credibility_base || 0))));
    const corroboration =
      sources.length >= 3 ? 0.25 :
      sources.length === 2 ? 0.15 : 0.00;

    const hasGeo = group.some(e => Number.isFinite(Number(e.latitude)) && Number.isFinite(Number(e.longitude)));
    const hasNamedLocation = group.some(e => meaningfulLoc(e) !== norm(e.country || ''));
    const geo = hasGeo ? 0.15 : (hasNamedLocation ? 0.10 : 0.03);

    const freshest = Math.min(...group.map(e => hoursOld(e.event_time)));
    const time =
      freshest <= 24 ? 0.15 :
      freshest <= 72 ? 0.12 :
      freshest <= 168 ? 0.08 : 0.03;

    const sameCountry = new Set(group.map(e => norm(e.country))).size <= 1;
    const sameType = new Set(group.map(e => norm(e.event_type))).size <= 1;
    const consistency = sameCountry && sameType ? 0.15 : 0.08;

    const confidence = Math.min(1, credibility + corroboration + geo + time + consistency);
    const status =
      confidence >= 0.70 ? 'HIGH / VERIFIED' : confidence >= 0.50 ? 'ACTIONABLE / ANALYZE' :
      confidence >= 0.40 ? 'MEDIUM / NEEDS VERIFICATION' :
      'LOW / MONITOR';

    output.push({
      json: {
        event_id: `ACI-${norm(primary.country).toUpperCase().replace(/\s+/g, '-').slice(0, 10)}-${Date.now()}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`,
        event_type: primary.event_type,
        sub_event_type: primary.sub_event_type || '',
        country: primary.country,
        admin1: primary.admin1 || '',
        location: primary.location,
        latitude: primary.latitude,
        longitude: primary.longitude,
        event_time: primary.event_time,
        title: primary.title,
        description: primary.description,
        fatalities: primary.fatalities || 0,
        actors: primary.actors || [],
        sources,
        source_count: sources.length,
        evidence: group.map(e => ({
          source: e.source,
          title: e.title,
          url: e.source_url,
          time: e.event_time,
          description: (e.description || '').slice(0, 300)
        })),
        scoring: {
          source_credibility: +credibility.toFixed(2),
          independent_corroboration: +corroboration.toFixed(2),
          geographic_agreement: +geo.toFixed(2),
          temporal_agreement: +time.toFixed(2),
          cross_source_consistency: +consistency.toFixed(2)
        },
        confidence: +confidence.toFixed(2),
        status,
        alert_required: confidence >= 0.50,
        generated_at: new Date().toISOString()
      }
    });
  }
}

return output
  .sort((a, b) => b.json.confidence - a.json.confidence)
  .slice(0, 10);

const items=$input.all(); const originals=$('Throttle Groq Requests — 4s').all();
return items.map((item,index)=>{
 const input=item.json||{}; const original=originals[index]?.json||input;
 const failed=input.error||input.statusCode===429||input.code===429||(input.message&&String(input.message).toLowerCase().includes('too many requests'));
 if(failed){return {json:{...original,ai:null,headline:original.title||`${original.event_type} — ${original.location||original.country}`,intelligence_summary:original.description||`A ${original.event_type} event was reported.`,severity:original.confidence>=0.70?'Elevated':'Monitor',recommended_actions:['Review supporting evidence','Continue monitoring for independent corroboration'],information_gaps:original.source_count<2?['Independent corroborating source']:[],llm_status:'rate_limited_fallback'}};}
 let txt=input.choices?.[0]?.message?.content??input.text??input.message?.content??input.output??'{}';
 if(typeof txt!=='string') txt=JSON.stringify(txt);
 txt=txt.replace(/^```json\s*/i,'').replace(/```$/g,'').trim();
 let ai={}; try{ai=JSON.parse(txt)}catch{ai={summary:txt&&txt.length>5?txt:(original.description||original.title||'')}}
 return {json:{...original,ai,headline:ai.headline||original.title||`${original.event_type} — ${original.location||original.country}`,intelligence_summary:ai.summary||original.description||`A ${original.event_type} event was reported.`,severity:ai.severity||(original.confidence>=0.85?'High':original.confidence>=0.70?'Elevated':'Monitor'),recommended_actions:Array.isArray(ai.recommended_actions)?ai.recommended_actions:['Review supporting evidence'],information_gaps:Array.isArray(ai.information_gaps)?ai.information_gaps:(original.source_count<2?['Independent corroborating source']:[]),llm_status:'ok'}};
});

