const all = $input.all().map(i => i.json);

const high = all.filter(e => e.confidence >= 0.70).length;
const medium = all.filter(e => e.confidence >= 0.40 && e.confidence < 0.70).length;
const low = all.filter(e => e.confidence < 0.40).length;

const sourcesUsed = [...new Set(all.flatMap(e => e.sources || []))];

return [{
  json: {
    workflow_result: 'Africa Crisis Intelligence pipeline completed',
    run_summary: {
      total_events: all.length,
      high_confidence: high,
      medium_confidence: medium,
      low_confidence: low,
      sources_used: sourcesUsed,
      generated_at: new Date().toISOString()
    },
    events: all,
    note: 'Events ≥0.50 are eligible for analysis/alerts; previously alerted events skip Groq.'
  }
}];

const events = $json.events || [];
const cfg = $('Config + Date Window1').first().json;
const bbox = cfg.bbox;

function inside(lat, lon) {
  if (!bbox) return true;
  return Number.isFinite(lat) && Number.isFinite(lon) &&
    lat >= bbox.minLat && lat <= bbox.maxLat &&
    lon >= bbox.minLon && lon <= bbox.maxLon;
}

return events
  .map(e => {
    const category = e.categories?.[0]?.title || 'Disaster';
    const geo = e.geometry?.[0] || {};
    const coords = geo.coordinates || [];
    const lon = Number(coords[0]);
    const lat = Number(coords[1]);

    return {
      source: 'NASA',
      source_type: 'satellite_alert',
      source_event_id: e.id,
      event_type: category,
      sub_event_type: '',
      title: e.title || category,
      description: e.description || `NASA EONET detected ${category}`,
      country: cfg.target_country || '',
      admin1: '',
      location: e.title || cfg.target_country,
      latitude: Number.isFinite(lat) ? lat : null,
      longitude: Number.isFinite(lon) ? lon : null,
      event_time: geo.date || new Date().toISOString(),
      actors: [],
      fatalities: 0,
      source_url: e.sources?.[0]?.url || 'https://eonet.gsfc.nasa.gov',
      credibility_base: 0.30,
      raw: e
    };
  })
  .filter(e => !bbox || inside(e.latitude, e.longitude))
  .map(json => ({ json }));

const features = $json.features || [];
const cfg = $('Config + Date Window1').first().json;
const bbox = cfg.bbox;

function inside(lat, lon) {
  if (!bbox) return true;
  return Number.isFinite(lat) && Number.isFinite(lon) &&
    lat >= bbox.minLat && lat <= bbox.maxLat &&
    lon >= bbox.minLon && lon <= bbox.maxLon;
}

return features
  .map(f => {
    const props = f.properties || {};
    const coords = f.geometry?.coordinates || [];
    const lon = Number(coords[0]);
    const lat = Number(coords[1]);

    return {
      source: 'USGS',
      source_type: 'seismic_alert',
      source_event_id: f.id,
      event_type: 'Earthquake',
      sub_event_type: '',
      title: props.title || 'Earthquake',
      description: `Magnitude ${props.mag} earthquake near ${props.place}`,
      country: cfg.target_country || '',
      admin1: '',
      location: props.place || cfg.target_country,
      latitude: Number.isFinite(lat) ? lat : null,
      longitude: Number.isFinite(lon) ? lon : null,
      event_time: new Date(props.time || Date.now()).toISOString(),
      actors: [],
      fatalities: 0,
      source_url: props.url || 'https://earthquake.usgs.gov',
      credibility_base: 0.30,
      raw: f
    };
  })
  .filter(e => !bbox || inside(e.latitude, e.longitude))
  .map(json => ({ json }));

