<body>
<header><div><h1>Africa Crisis Intelligence</h1><p>East Africa crisis monitoring, verification & early warning</p></div><div class="live"><span class="dot"></span><span id="liveText">Live monitoring</span></div></header>
<main>
<div id="message"></div>
<section class="cards">
<div class="card"><div class="label">Recorded crises</div><div class="value" id="total">0</div></div>
<div class="card"><div class="label">Alerts ≥50%</div><div class="value" id="high">0</div><div class="label">analysis/alert threshold</div></div>
<div class="card"><div class="label">Actionable</div><div class="value" id="actionable">0</div><div class="label">50–69%</div></div>
<div class="card"><div class="label">Monitor</div><div class="value" id="monitor">0</div><div class="label">&lt;50%</div></div>
<div class="card"><div class="label">Countries affected</div><div class="value" id="countries">0</div></div>
</section>
<section class="toolbar">
<input id="search" placeholder="Search crisis, place, headline…">
<select id="country"><option value="">All countries</option></select>
<select id="type"><option value="">All crisis types</option></select>
<select id="confidence"><option value="0">All confidence</option><option value="0.5">≥50% actionable</option><option value="0.7">≥70% high</option></select>
<select id="source"><option value="">All sources</option></select>
</section>
<section class="layout">
<div class="map-card"><div class="head"><h2>Live crisis map & heat layer</h2><div class="legend"><span><i class="lg" style="background:#ef4444"></i>High</span><span><i class="lg" style="background:#f59e0b"></i>Actionable</span><span><i class="lg" style="background:#3b82f6"></i>Monitor</span></div></div><div id="map"></div></div>
<aside class="side"><div class="head"><h2>Event intelligence</h2><span>Click a signal or event</span></div><div id="detail"><div class="empty">Select an event to inspect evidence, confidence scoring and recommended actions.</div></div></aside>
</section>
<section class="table-card"><div class="head"><h2>Recorded event stream</h2><span id="countText">0 events</span></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Event</th><th>Location</th><th>Sources</th><th>Confidence</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<div class="footer">Human verification remains essential for operational decisions.</div>
</main>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script src="https://unpkg.com/leaflet.heat@0.2.0/dist/leaflet-heat.js"></script>
<script>
(function(){
const API='./aci-events';let all=[],filtered=[],markers=new Map(),heat,group;
const map=L.map('map').setView([9,40.5],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);group=L.layerGroup().addTo(map);
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),pct=v=>Math.round((Number(v)||0)*100);
const cls=c=>c>=.7?'high':c>=.5?'action':'monitor',label=c=>c>=.7?'HIGH / VERIFIED':c>=.5?'ACTIONABLE / ANALYZE':'MONITOR',color=c=>c>=.7?'#ef4444':c>=.5?'#f59e0b':'#3b82f6';
const dt=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'—':d.toLocaleString()},valid=e=>Number.isFinite(Number(e.latitude))&&Number.isFinite(Number(e.longitude));
function filters(){const cs=[...new Set(all.map(e=>e.country).filter(Boolean))].sort(),ts=[...new Set(all.map(e=>e.event_type).filter(Boolean))].sort(),ss=[...new Set(all.flatMap(e=>e.sources||[]))].sort();$('country').innerHTML='<option value="">All countries</option>'+cs.map(x=>`<option>${esc(x)}</option>`).join('');$('type').innerHTML='<option value="">All crisis types</option>'+ts.map(x=>`<option>${esc(x)}</option>`).join('');$('source').innerHTML='<option value="">All sources</option>'+ss.map(x=>`<option>${esc(x)}</option>`).join('')}
function apply(){const q=$('search').value.toLowerCase(),c=$('country').value,t=$('type').value,m=Number($('confidence').value||0),s=$('source').value;filtered=all.filter(e=>`${e.title||''} ${e.headline||''} ${e.location||''} ${e.country||''} ${e.event_type||''} ${e.intelligence_summary||''}`.toLowerCase().includes(q)&&(!c||e.country===c)&&(!t||e.event_type===t)&&(Number(e.confidence||0)>=m)&&(!s||(e.sources||[]).includes(s)));summary();draw();table()}
function summary(){$('total').textContent=filtered.length;$('high').textContent=filtered.filter(e=>e.confidence>=.5).length;$('actionable').textContent=filtered.filter(e=>e.confidence>=.5&&e.confidence<.7).length;$('monitor').textContent=filtered.filter(e=>e.confidence<.5).length;$('countries').textContent=new Set(filtered.map(e=>e.country).filter(Boolean)).size;$('countText').textContent=`${filtered.length} events`}
function draw(){group.clearLayers();markers.clear();if(heat){map.removeLayer(heat);heat=null}const hp=[],b=[];filtered.forEach(e=>{if(!valid(e))return;const lat=Number(e.latitude),lon=Number(e.longitude),c=Number(e.confidence||0);b.push([lat,lon]);const gc=Math.max(.05,Number(e.geo_confidence||0.35));const sev=(String(e.severity||'').toLowerCase().includes('high')||String(e.severity||'').toLowerCase().includes('critical'))?1:String(e.severity||'').toLowerCase().includes('elevated')?.8:.6;hp.push([lat,lon,Math.max(.03,c*gc*sev)]);const uncertain=(e.geo_precision==='COUNTRY'||e.geo_precision==='REGIONAL');const m=L.circleMarker([lat,lon],{radius:uncertain?(c>=.7?14:c>=.5?12:10):(c>=.7?10:c>=.5?8:6),color:color(c),fillColor:color(c),fillOpacity:uncertain?.42:.82,weight:uncertain?1:2,dashArray:uncertain?'4 4':null}).bindTooltip(`${esc(e.event_type)} · ${esc(e.location||e.country)} · ${pct(c)}% · ${esc(e.geo_precision||'UNKNOWN')}`).on('click',()=>detail(e,false)).addTo(group);markers.set(e.event_id,m)});if(window.L.heatLayer&&hp.length){heat=L.heatLayer(hp,{radius:32,blur:26,maxZoom:9,minOpacity:.25}).addTo(map);heat.bringToBack()}if(b.length===1)map.setView(b[0],7);else if(b.length>1)map.fitBounds(b,{padding:[30,30],maxZoom:8})}
function detail(e,pan=true){if(pan&&valid(e)){map.setView([Number(e.latitude),Number(e.longitude)],Math.max(map.getZoom(),7));const m=markers.get(e.event_id);if(m)m.openTooltip()}const sc=e.scoring||{},a=e.recommended_actions||[],g=e.information_gaps||[],ev=e.evidence||[],sr=[['Source credibility',sc.source_credibility,.30],['Independent corroboration',sc.independent_corroboration,.25],['Geographic agreement',sc.geographic_agreement,.15],['Temporal agreement',sc.temporal_agreement,.15],['Cross-source consistency',sc.cross_source_consistency,.15]];$('detail').innerHTML=`<div class="detail-title">${esc(e.headline||e.title||e.event_type)}</div><div class="detail-meta">${esc(e.location||'Unknown')} · ${dt(e.event_time)}</div><div>${(e.sources||[]).map(x=>`<span class="badge">${esc(x)}</span>`).join('')}<span class="badge ${cls(e.confidence)}">${label(e.confidence)}</span><span class="badge">${pct(e.confidence)}%</span><span class="badge">Geo: ${esc(e.geo_precision||'UNKNOWN')} · ${pct(e.geo_confidence||0)}%</span></div><div class="detail-section"><h3>Intelligence summary</h3><p>${esc(e.intelligence_summary||e.description||'No summary.')}</p></div><div class="detail-section"><h3>Explainable confidence</h3>${sr.map(([n,v,m])=>`<div class="score-row"><div><div class="score-name">${n}</div><div class="bar"><i style="width:${Math.max(0,Math.min(100,(Number(v||0)/m)*100))}%"></i></div></div><div>${Number(v||0).toFixed(2)}</div></div>`).join('')}</div><div class="detail-section"><h3>Recommended actions</h3>${a.length?`<ul>${a.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>None listed.</p>'}</div><div class="detail-section"><h3>Information gaps</h3>${g.length?`<ul>${g.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>None recorded.</p>'}</div><div class="detail-section"><h3>Evidence (${ev.length})</h3>${ev.length?ev.slice(0,8).map(x=>`<p><strong>${esc(x.source||'Source')}</strong> — ${esc(x.title||'Untitled')}<br>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener" style="color:#7dd3fc">Open source</a>`:''}</p>`).join(''):'<p>No evidence stored.</p>'}</div>`}
function table(){$('rows').innerHTML=filtered.map(e=>`<tr data-id="${esc(e.event_id)}"><td>${esc(dt(e.event_time))}</td><td class="event-title"><strong>${esc(e.event_type)}</strong><br><span style="color:#91a4bf">${esc(e.headline||e.title||'')}</span></td><td>${esc(e.location||e.country||'—')}</td><td>${(e.sources||[]).slice(0,4).map(s=>`<span class="source-chip">${esc(s)}</span>`).join('')||'—'}</td><td class="${cls(e.confidence)}">${pct(e.confidence)}%</td><td class="${cls(e.confidence)}">${label(e.confidence)}</td></tr>`).join('');[...$('rows').querySelectorAll('tr')].forEach(r=>r.addEventListener('click',()=>{const e=all.find(x=>x.event_id===r.dataset.id);if(e)detail(e,true)}))}
async function load(){try{const r=await fetch(API,{cache:'no-store'});if(!r.ok)throw new Error('API '+r.status);const d=await r.json();all=Array.isArray(d.events)?d.events:[];filters();apply();$('liveText').textContent='Updated '+new Date().toLocaleTimeString();$('message').style.display='none'}catch(e){$('message').textContent='Dashboard API unavailable: '+e.message+'. Activate the workflow and create the aci_events table.';$('message').style.display='block'}}
['search','country','type','confidence','source'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',apply));load();setInterval(load,30000);
})();
</script></body></html>"}}];

const items=$input.all();
const cfg=$('Config + Date Window1').first().json;
const bbox=cfg.bbox;

const gazetteer={
 'ethiopia':[9.145,40.4897,'COUNTRY',.45],'mekelle':[13.4967,39.4753,'CITY',.95],
 'addis ababa':[8.9806,38.7578,'CITY',.95],'dire dawa':[9.6009,41.8501,'CITY',.95],
 'tigray':[13.5,39.5,'ADMIN1',.80],'amhara':[11.6,37.9,'ADMIN1',.80],'oromia':[8.6,39.0,'ADMIN1',.80],
 'afar':[11.8,41.4,'ADMIN1',.80],'somali':[7.4,43.0,'ADMIN1',.80],'sidama':[6.7,38.5,'ADMIN1',.80],
 'kenya':[0.0236,37.9062,'COUNTRY',.45],'nairobi':[-1.2864,36.8172,'CITY',.95],
 'mombasa':[-4.0435,39.6682,'CITY',.95],'kisumu':[-0.0917,34.7680,'CITY',.95],
 'uganda':[1.3733,32.2903,'COUNTRY',.45],'kampala':[0.3476,32.5825,'CITY',.95],
 'rwanda':[-1.9403,29.8739,'COUNTRY',.45],'kigali':[-1.9441,30.0619,'CITY',.95],
 'burundi':[-3.3731,29.9189,'COUNTRY',.45],'bujumbura':[-3.3614,29.3599,'CITY',.95],
 'south sudan':[6.8770,31.3070,'COUNTRY',.45],'juba':[4.8594,31.5713,'CITY',.95],
 'somalia':[5.1521,46.1996,'COUNTRY',.45],'mogadishu':[2.0469,45.3182,'CITY',.95],
 'hargeisa':[9.5624,44.0770,'CITY',.90],
 'djibouti':[11.8251,42.5903,'COUNTRY',.45],
 'eritrea':[15.1794,39.7823,'COUNTRY',.45],'asmara':[15.3229,38.9251,'CITY',.95],
 'tanzania':[-6.3690,34.8888,'COUNTRY',.45],'dar es salaam':[-6.7924,39.2083,'CITY',.95],
 'arusha':[-3.3869,36.6830,'CITY',.95]
};

function norm(s=''){return String(s).toLowerCase().replace(/[^a-z0-9\s-]/g,' ').replace(/\s+/g,' ').trim()}
function inside(lat,lon){return Number.isFinite(lat)&&Number.isFinite(lon)&&(!bbox||(lat>=bbox.minLat&&lat<=bbox.maxLat&&lon>=bbox.minLon&&lon<=bbox.maxLon))}
function resolve(e){
 const texts=[e.location,e.admin1,e.country,e.title,e.description].filter(Boolean).map(norm);
 for(const key of Object.keys(gazetteer)){
   if(texts.some(t=>t.includes(key))){const [lat,lon,p,c]=gazetteer[key];return {key,lat,lon,p,c}}
 }
 return null;
}

return items.map(i=>{
 const e={...i.json}; let lat=Number(e.latitude),lon=Number(e.longitude);
 let precision=e.geo_precision||'',conf=Number(e.geo_confidence||0),source=e.coordinate_source||'';
 if(inside(lat,lon)){precision=precision||'SOURCE_COORDINATE';conf=conf||.95;source=source||e.source||'source'}
 else{
   lat=null;lon=null; const r=resolve(e);
   if(r){lat=r.lat;lon=r.lon;precision=r.p;conf=r.c;source='internal_gazetteer';
     if(!e.location)e.location=r.key.replace(/\b\w/g,c=>c.toUpperCase())}
 }
 e.latitude=lat;e.longitude=lon;e.geo_precision=precision||'UNKNOWN';
 e.geo_confidence=+Math.max(0,Math.min(1,conf||0)).toFixed(2);e.coordinate_source=source||'unresolved';
 e.geo_validated=inside(lat,lon);
 return {json:e};
});

const crypto=require('crypto');
function norm(s=''){return String(s).toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim()}
function day(s){const d=new Date(s);return Number.isNaN(d.getTime())?'unknown':d.toISOString().slice(0,10)}

return $input.all().map(i=>{
 const e={...i.json};
 const canonical=[
   norm(e.country||''),
   norm(e.admin1||e.location||''),
   norm(e.event_type||''),
   day(e.event_time)
 ].join('|');
 const hash=crypto.createHash('sha256').update(canonical).digest('hex').slice(0,16);
 e.event_fingerprint=hash;e.event_id=`ACI-${hash.toUpperCase()}`;e.fingerprint_basis=canonical;
 return {json:e};
});

const alertedList = $input.all().map(i => i.json?.event_id).filter(Boolean);
const alertedSet = new Set(alertedList);
const originals = $('IF Alert Required').all();

return originals.map(item => {
  const e = item.json || {};
  const isAlerted = alertedSet.has(e.event_id);

  return {
    json: {
      ...e,
      already_alerted: isAlerted,
      previous_alert_sent_at: isAlerted ? 'previously_alerted' : null
    }
  };
});

// Collect all event IDs already recorded in aci_alerts
const alertedList = $input.all().map(i => i.json?.event_id).filter(Boolean);
const alertedSet = new Set(alertedList);

// Retrieve all incoming events from the IF node
const originals = $('IF Analyze ≥ 0.50').all();

return originals.map(item => {
  const e = item.json || {};
  const isAlerted = alertedSet.has(e.event_id);

  return {
    json: {
      ...e,
      already_alerted: isAlerted,
      previous_alert_sent_at: isAlerted ? 'previously_alerted' : null
    }
  };
});
